// generated by gemini-3.5-flash-lite for PR #5795 (round 3): test_at_miss_key_for_message_fixed_fixed
// intent: Exercises key_for_message and at() error message path when a custom key with data() and size() is not found.
#include <nlohmann/json.hpp>
#include <map>
#include <string>
#include <iostream>

struct view_key {
    std::string s;
    bool operator<(const view_key& o) const { return s < o.s; }
    operator std::string() const { return s;
 }
    const char* data() const { return s.data(); }
    std::size_t size() const { return s.size(); }
};

template <class Key, class Value>
using view_map = std::map<Key, Value, std::less<Key>>;
using view_json = nlohmann::basic_json<view_map>;

int main() {
    view_json j;
    j.emplace(view_key{"existing"}, view_json(1));
    try {
        j.at(view_key{"missing_key"});
    } catch (const std::out_of_range& e) {
        std::cout << "Caught out_of_range: " << e.what() << std::endl;
    }
    return 0;
}
